import{_ as a,o as r,c as t,a5 as o}from"./chunks/framework.BwlBv862.js";const f=JSON.parse('{"title":"TikTools 4.2.1-rc.2 候補の記録","description":"","frontmatter":{"title":"TikTools 4.2.1-rc.2 候補の記録","docId":"releases.4.2.1-rc.2","translationKey":"releases.4.2.1-rc.2","locale":"ja","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"af1ea83a9bb29fd23f3e4c086d976fb5abecaff8e20965cc6db9b5c64d5b191e","translationRevision":"faabaeafc27967be03ad78a10c1b345efa74e7e7bc73feb2efad99661c29fa5e","order":20},"headers":[],"relativePath":"ja/releases/4.2.1-rc.2.md","filePath":"ja/releases/4.2.1-rc.2.md","lastUpdated":1794611623000}'),c={name:"ja/releases/4.2.1-rc.2.md"};function i(d,e,l,s,n,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="tiktools-421-rc2" tabindex="-1">TikTools 4.2.1-rc.2 <a class="header-anchor" href="#tiktools-421-rc2" aria-label="Permalink to &quot;TikTools 4.2.1-rc.2 {#tiktools-421-rc2}&quot;">​</a></h1><h2 id="goal-status-and-prerequisites" tabindex="-1">目的・状況・前提条件 <a class="header-anchor" href="#goal-status-and-prerequisites" aria-label="Permalink to &quot;目的・状況・前提条件 {#goal-status-and-prerequisites}&quot;">​</a></h2><p>RC2 の過去の記録から、RC1 で再現した変更の並行読み取りの修正を理解します。Actions 無効中にローカルでビルドした Linux AppImage、DEB、可搬型パッケージが対象です。現在の取得可否や新規 Windows パッケージは確認しません。<a href="https://github.com/nglmercer/TikTools-app/releases" target="_blank" rel="noreferrer">リリース一覧</a> から選び、チェックサムを保管して分離プロファイルで試します。</p><p>Cloud 復旧と共同操作は実験段階です。ニックネーム検索には引き続きバックエンド <code>6a69c99</code> と移行 <code>20261113000001_remote_invitation_recipients.sql</code> が必要で、アプリのパッケージはそれらを配置しません。</p><h2 id="correction-and-expected-behavior" tabindex="-1">修正と期待される動作 <a class="header-anchor" href="#correction-and-expected-behavior" aria-label="Permalink to &quot;修正と期待される動作 {#correction-and-expected-behavior}&quot;">​</a></h2><p>変更・競合一覧とプロトコル選択は、製品の変更スロットを予約せずプロトコル観測を共有します。無関係のパッケージジャーナルがスロットを使用中でも、ツールバー・パネルの読み取りを完了できます。書き込みの防護、アカウント分離、明示的移行判断は維持します。</p><p>アカウント検査はログアウト、遷移保留、置換セッションを拒否します。ローカル比較の読み取りで認証情報を復元したり Cloud 要求を開始したりしません。失敗時はネイティブの理由とローカル再読込を表示します。この再試行は送信、取得、レコード解決を行いません。</p><h2 id="check-the-candidate" tabindex="-1">候補を確認する <a class="header-anchor" href="#check-the-candidate" aria-label="Permalink to &quot;候補を確認する {#check-the-candidate}&quot;">​</a></h2><ol><li>表示 <code>4.2.1-rc.2</code> を記録し、分離プロファイルでプラグイン → 変更を開きます。</li><li>ツールバーとパネルから比較を開くか再読み込みします。失敗時は「すべて同期済み」とせず理由を保持するはずです。</li><li>ローカル再試行が、保留列の変更やリモートレコード適用なしで比較を再読込することを確認します。</li><li>アカウント・セッション遷移を別に記録します。影響プロファイルの再現では <a href="./4.2.1-rc.1.html">RC1 の移行手順</a> と比べます。</li></ol><h2 id="recorded-validation-and-recovery" tabindex="-1">記録済み検証と復旧 <a class="header-anchor" href="#recorded-validation-and-recovery" aria-label="Permalink to &quot;記録済み検証と復旧 {#recorded-validation-and-recovery}&quot;">​</a></h2><p>原記録には決定的な32読み取りの回帰、CloudAuth・同期・ネイティブ・フロントエンドの検査、空の分離プロファイルでの最適化 AppImage 起動が記載されています。インストーラー内容と可搬アーカイブも確認されました。その起動ではサインイン済み本番同期やメディア再生は試していません。</p><p>記録された AppImage の SHA-256 は <code>35fc26e7bc5875c5a3fe99bf6a84baf77af8ca63d1c8b8e61825881187d6091f</code> です。そのファイルを識別する値であり、実際の取得物には添付チェックサムを使います。</p><p>読み込みが失敗する場合は版、ネイティブエラー、要求 ID を保持して<a href="./../user/preferences/troubleshooting.html">診断</a> を使います。保留編集と競合を保全します。RC2 でも自動化はローカル基準、変数とオーバーレイは未完了、過去の SQLite ロック保持者は不明でした。古いバックエンドに欠けていた人物検索ルートがその後配置されたとは主張しません。</p><p><a href="https://github.com/nglmercer/TikTools-app/blob/80c5cb1fbfa45eaeb1c086c71320a15e565d8541/docs/RELEASE-4.2.1-rc.2.md" target="_blank" rel="noreferrer">元のリリース記録</a> は日付付き証拠として保持されています。<a href="./">リリース一覧に戻る</a>。</p>',14)])])}const b=a(c,[["render",i]]);export{f as __pageData,b as default};
